const raw =
  $input.first().json.text ||
  $input.first().json.content?.[0]?.text ||
  '';

const cleaned = raw
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

const start = cleaned.indexOf('{');
const end = cleaned.lastIndexOf('}');

if (start === -1 || end === -1) {
  throw new Error('No valid JSON object found');
}

const jsonString = cleaned.substring(start, end + 1);

try {
  const parsed = JSON.parse(jsonString);
  return [{ json: parsed }];
} catch (e) {
  throw new Error(
    'JSON parse failed: ' +
    e.message +
    '\n\nJSON:\n' +
    jsonString.substring(0, 3000)
  );
}

const item = $input.first();

// Vezi exact ce binary fields există
const binaryKeys = Object.keys(item.binary || {});
console.log('Binary keys found:', binaryKeys);

// Ia primul binary field indiferent de nume
if (binaryKeys.length === 0) {
  throw new Error('No binary data found. Keys: ' + JSON.stringify(Object.keys(item.json)));
}

return [{
  json: item.json,
  binary: item.binary
}];

return $input.all().map(item => ({
  json: {
    report_ref: item.json.report_ref || null,
    vessel_name: item.json.vessel_name || null,
    port: item.json.port || null,
    survey_date: item.json.survey_date || null,
    bl_number: item.json.bl_number || null,
    shipper: item.json.shipper || null,
    consignee: item.json.consignee || null,
    chapter_number: item.json.chapter_number,
    chapter_title: item.json.chapter_title,
    subchapter_number: item.json.subchapter_number || null,
    subchapter_title: item.json.subchapter_title || null,
    content: item.json.content
  }
}));

const data = $input.first().json;

// Inserează raportul master separat via HTTP sau Supabase node
// Pasează chunks mai departe cu report_ref atasat
return data.chunks.map(chunk => ({
  json: {
    report_ref: data.report_ref,
    chapter_number: chunk.chapter_number,
    chapter_title: chunk.chapter_title,
    subchapter_number: chunk.subchapter_number || null,
    subchapter_title: chunk.subchapter_title || null,
    content: chunk.content
  }
}));
